/**
 * scripts/art-process.ts
 *
 * Produces the committed pixel-art assets in public/art/.
 *
 * Honesty note (read before defending): the on-screen plate caption says the
 * illustration is "generated by script", NOT "AI-generated". This script draws
 * deterministic pixel-art with sharp. It is the offline fallback described in the
 * spec ("images made OFFLINE, either by script ... or manually in a free image
 * tool"). The companion scripts/gen-images.ts can fetch real AI art from
 * Pollinations into art-src/ when that free service is available; this script
 * will process those raw files if present, otherwise it generates a themed
 * placeholder so the app never ships a broken image slot.
 *
 * Two paths, both honest and disclosed in docs/ART_CREDITS.md:
 *  1) If art-src/{slot}.png exists (from gen-images.ts), it is processed with
 *     sharp: downscale -> palette-quantise -> nearest-neighbour upscale.
 *  2) Otherwise a deterministic themed pixel-art placeholder is drawn and written
 *     to public/art/{slot}.png.
 *
 * No network access. sharp is a dev dependency and is never imported by app code
 * (eslint and release-check both verify this).
 *
 * Run: npm run art:process
 */
import sharp from "sharp";
import fs from "node:fs";
import path from "node:path";

import { ENABLED_REALMS, type RealmId } from "../lib/config";

// Output dimensions match the ArtImage layout (480x320). We render at a small
// "logical" resolution and upscale with nearest-neighbour for the chunky pixel look.
const OUT_W = 480;
const OUT_H = 320;
const LW = 120;
const LH = 80;

type RGB = readonly [number, number, number];

interface Palette {
  skyTop: RGB;
  skyBottom: RGB;
  ground: RGB;
  accent: RGB;
  dark: RGB;
  highlight: RGB;
  mid: RGB;
}

const clampByte = (v: number) => Math.max(0, Math.min(255, Math.round(v)));
const lerpC = (a: RGB, b: RGB, t: number): RGB => [
  clampByte(a[0] + (b[0] - a[0]) * t),
  clampByte(a[1] + (b[1] - a[1]) * t),
  clampByte(a[2] + (b[2] - a[2]) * t),
];

/** Minimal RGBA canvas with the primitives a pixel-art generator needs. */
class Canvas {
  readonly buf: Buffer;
  constructor(readonly w: number, readonly h: number) {
    this.buf = Buffer.alloc(w * h * 4, 0); // transparent by default
  }
  px(x: number, y: number, c: RGB, a = 255): void {
    if (x < 0 || y < 0 || x >= this.w || y >= this.h) return;
    const i = (y * this.w + x) * 4;
    this.buf[i] = c[0];
    this.buf[i + 1] = c[1];
    this.buf[i + 2] = c[2];
    this.buf[i + 3] = a;
  }
  rect(x: number, y: number, w: number, h: number, c: RGB, a = 255): void {
    for (let j = 0; j < h; j++) for (let i = 0; i < w; i++) this.px(x + i, y + j, c, a);
  }
  disc(cx: number, cy: number, r: number, c: RGB, a = 255): void {
    for (let y = -r; y <= r; y++)
      for (let x = -r; x <= r; x++) if (x * x + y * y <= r * r) this.px(cx + x, cy + y, c, a);
  }
  ellipse(cx: number, cy: number, rx: number, ry: number, c: RGB, a = 255): void {
    for (let y = -ry; y <= ry; y++)
      for (let x = -rx; x <= rx; x++)
        if ((x * x) / (rx * rx) + (y * y) / (ry * ry) <= 1) this.px(cx + x, cy + y, c, a);
  }
  line(x0: number, y0: number, x1: number, y1: number, c: RGB, a = 255): void {
    const dx = Math.abs(x1 - x0);
    const dy = -Math.abs(y1 - y0);
    const sx = x0 < x1 ? 1 : -1;
    const sy = y0 < y1 ? 1 : -1;
    let err = dx + dy;
    while (true) {
      this.px(x0, y0, c, a);
      if (x0 === x1 && y0 === y1) break;
      const e2 = 2 * err;
      if (e2 >= dy) {
        err += dy;
        x0 += sx;
      }
      if (e2 <= dx) {
        err += dx;
        y0 += sy;
      }
    }
  }
  /** Filled isosceles triangle, apex at (cx, topY), base centred on (cx, baseY). */
  triangle(cx: number, baseY: number, halfW: number, topY: number, c: RGB, a = 255): void {
    const span = baseY - topY || 1;
    for (let y = topY; y <= baseY; y++) {
      const hw = Math.round((halfW * (y - topY)) / span);
      for (let x = -hw; x <= hw; x++) this.px(cx + x, y, c, a);
    }
  }
  gradient(c: RGB, d: RGB): void {
    for (let y = 0; y < this.h; y++) this.rect(0, y, this.w, 1, lerpC(c, d, y / (this.h - 1)));
  }
}

async function toPng(c: Canvas, opaque: boolean): Promise<Buffer> {
  let img = sharp(c.buf, { raw: { width: c.w, height: c.h, channels: 4 } }).resize(OUT_W, OUT_H, {
    kernel: "nearest",
  });
  // Opaque scenes/plates use a small palette for tiny files; alpha characters keep
  // full RGBA so transparency stays clean (we only ever write 0/255 alpha pixels).
  img = opaque ? img.png({ compressionLevel: 9, palette: true, colors: 48 }) : img.png({ compressionLevel: 9 });
  return img.toBuffer();
}

// ── palettes ─────────────────────────────────────────────────────────────────
const REALM_THEME_ID: Record<RealmId, string> = {
  "g5-fractions": "forest",
  "g5-decimals": "dunes",
  "g5-volume": "volcano",
  "g6-ratios": "reef",
  "g6-fracdiv": "quarry",
  "g6-area": "atoll",
};

const THEME: Record<string, Palette> = {
  forest: { skyTop: [28, 40, 62], skyBottom: [40, 86, 64], ground: [22, 52, 34], accent: [132, 200, 120], dark: [12, 28, 22], highlight: [184, 228, 150], mid: [44, 84, 58] },
  dunes: { skyTop: [58, 40, 72], skyBottom: [196, 120, 66], ground: [206, 142, 62], accent: [239, 189, 93], dark: [96, 54, 26], highlight: [255, 219, 140], mid: [156, 96, 54] },
  volcano: { skyTop: [34, 14, 22], skyBottom: [180, 74, 42], ground: [58, 26, 20], accent: [231, 144, 88], dark: [22, 10, 10], highlight: [255, 140, 76], mid: [122, 42, 32] },
  reef: { skyTop: [14, 32, 60], skyBottom: [26, 108, 124], ground: [12, 60, 70], accent: [112, 213, 209], dark: [8, 36, 44], highlight: [162, 242, 236], mid: [32, 92, 102] },
  quarry: { skyTop: [46, 46, 62], skyBottom: [94, 94, 110], ground: [60, 60, 72], accent: [180, 175, 208], dark: [28, 28, 38], highlight: [218, 210, 242], mid: [72, 72, 86] },
  atoll: { skyTop: [28, 60, 92], skyBottom: [60, 140, 124], ground: [44, 92, 60], accent: [157, 200, 121], dark: [12, 44, 28], highlight: [202, 232, 160], mid: [52, 112, 82] },
  landing: { skyTop: [14, 16, 38], skyBottom: [40, 46, 84], ground: [18, 40, 32], accent: [242, 185, 47], dark: [10, 18, 30], highlight: [246, 215, 122], mid: [32, 54, 64] },
  map: { skyTop: [22, 42, 72], skyBottom: [22, 42, 72], ground: [60, 110, 72], accent: [242, 185, 47], dark: [14, 26, 40], highlight: [246, 215, 122], mid: [40, 72, 58] },
  library: { skyTop: [40, 28, 20], skyBottom: [56, 40, 28], ground: [48, 34, 24], accent: [242, 185, 47], dark: [24, 16, 12], highlight: [232, 200, 150], mid: [72, 52, 32] },
};

const HERO: Palette = { skyTop: [20, 24, 40], skyBottom: [30, 40, 70], ground: [20, 24, 40], accent: [242, 185, 47], dark: [30, 40, 60], highlight: [180, 190, 210], mid: [70, 100, 160] };
const MENTOR: Palette = { skyTop: [20, 24, 40], skyBottom: [30, 40, 70], ground: [20, 24, 40], accent: [120, 210, 200], dark: [30, 40, 60], highlight: [240, 240, 240], mid: [70, 90, 150] };

const SKIN: RGB = [232, 200, 150];
const BOOK_COLORS: RGB[] = [[180, 70, 70], [70, 120, 180], [120, 150, 70], [170, 120, 60], [110, 80, 150]];

// ── primitives per theme ──────────────────────────────────────────────────────
function stars(c: Canvas, p: Palette, count: number, seed: number): void {
  // deterministic pseudo-random based on a seed (no Math.random -> reproducible builds)
  let s = seed;
  const rand = () => {
    s = (s * 1103515245 + 12345) & 0x7fffffff;
    return s / 0x7fffffff;
  };
  for (let i = 0; i < count; i++) {
    const x = Math.floor(rand() * c.w);
    const y = Math.floor(rand() * (c.h * 0.5));
    c.px(x, y, p.highlight, rand() > 0.3 ? 255 : 150);
  }
}

function tree(c: Canvas, x: number, baseY: number, h: number, p: Palette): void {
  c.rect(x - 1, baseY - h, 2, h, p.dark);
  c.triangle(x, baseY - h + 2, 5, baseY - h - 4, p.mid);
  c.triangle(x, baseY - h - 2, 6, baseY - h - 11, p.accent);
}

function dune(c: Canvas, cx: number, baseY: number, r: number, p: Palette): void {
  for (let x = -r; x <= r; x++) {
    const hh = Math.round(Math.sqrt(Math.max(0, r * r - x * x)));
    for (let y = 0; y < hh; y++) c.px(cx + x, baseY - y, lerpC(p.ground, p.dark, (y / r) * 0.25));
  }
  c.line(cx - r, baseY, cx + r, baseY, p.highlight, 160);
}

function volcano(c: Canvas, cx: number, baseY: number, halfW: number, p: Palette): void {
  c.triangle(cx, baseY, halfW, baseY - 26, p.dark);
  c.rect(cx - 4, baseY - 28, 9, 4, p.accent);
  c.line(cx, baseY - 27, cx - 7, baseY - 10, p.accent);
  c.line(cx + 1, baseY - 27, cx + 7, baseY - 12, p.highlight);
}

function coral(c: Canvas, x: number, baseY: number, h: number, p: Palette): void {
  c.rect(x, baseY - h, 1, h, p.accent);
  c.rect(x - 1, baseY - h + 2, 1, 2, p.highlight);
  c.rect(x + 1, baseY - h + 4, 1, 3, p.highlight);
}

function stoneBlock(c: Canvas, x: number, y: number, w: number, h: number, p: Palette): void {
  c.rect(x, y, w, h, p.mid);
  c.rect(x, y, w, 1, p.highlight);
  c.rect(x, y + h - 1, w, 1, p.dark);
  c.rect(x, y, 1, h, p.highlight);
}

function island(c: Canvas, cx: number, baseY: number, r: number, p: Palette): void {
  for (let x = -r; x <= r; x++) {
    const hh = Math.round(Math.sqrt(Math.max(0, r * r - x * x)));
    for (let y = 0; y < hh; y++) c.px(cx + x, baseY - y, y < 3 ? p.ground : lerpC(p.ground, p.accent, 0.25));
  }
}

function scene(c: Canvas, slot: string, themeId: string): void {
  const p = THEME[themeId];
  c.gradient(p.skyTop, p.skyBottom);
  const groundY = Math.floor(c.h * 0.68);

  if (slot === "world-map") {
    drawWorldMap(c, p);
    return;
  }
  if (slot === "library") {
    drawLibrary(c, p);
    return;
  }

  // night skies get stars
  if (["landing", "volcano", "quarry", "reef"].includes(themeId) || slot === "landing") stars(c, p, 26, 7);
  // celestial body
  if (slot === "landing" || themeId === "volcano" || themeId === "reef" || themeId === "quarry") {
    c.disc(c.w - 22, 16, 7, p.highlight);
    c.disc(c.w - 19, 13, 6, p.skyTop);
  } else {
    c.disc(22, 16, 7, p.highlight);
  }

  c.rect(0, groundY, c.w, c.h - groundY, p.ground);

  switch (themeId) {
    case "forest":
      tree(c, 18, groundY + 12, 26, p);
      tree(c, 40, groundY + 14, 20, p);
      tree(c, 96, groundY + 12, 24, p);
      tree(c, 112, groundY + 14, 18, p);
      c.rect(0, groundY, c.w, 2, lerpC(p.ground, p.highlight, 0.3));
      break;
    case "dunes":
      dune(c, 30, groundY + 12, 26, p);
      dune(c, 78, groundY + 16, 32, p);
      dune(c, 108, groundY + 10, 20, p);
      break;
    case "volcano":
      volcano(c, 60, groundY + 14, 22, p);
      c.rect(0, groundY, c.w, 3, lerpC(p.accent, p.highlight, 0.3));
      break;
    case "reef":
      c.rect(0, groundY, c.w, c.h - groundY, lerpC(p.ground, p.mid, 0.4));
      coral(c, 24, groundY + 14, 18, p);
      coral(c, 60, groundY + 16, 24, p);
      coral(c, 96, groundY + 14, 16, p);
      break;
    case "quarry":
      stoneBlock(c, 10, groundY - 6, 22, 16, p);
      stoneBlock(c, 36, groundY - 2, 18, 12, p);
      stoneBlock(c, 70, groundY - 8, 26, 18, p);
      stoneBlock(c, 100, groundY, 16, 10, p);
      c.rect(0, groundY, c.w, c.h - groundY, p.ground);
      break;
    case "atoll":
      c.rect(0, groundY, c.w, c.h - groundY, lerpC(p.mid, p.ground, 0.5));
      island(c, 34, groundY + 6, 18, p);
      island(c, 86, groundY + 4, 22, p);
      break;
    default:
      break;
  }

  // landing gets a glowing gate motif
  if (slot === "landing") {
    c.rect(c.w / 2 - 6, groundY - 30, 12, 30, p.dark);
    c.disc(c.w / 2, groundY - 18, 4, p.accent);
  }
  if (slot === "grade-5") bigGlyph(c, "5", p);
  if (slot === "grade-6") bigGlyph(c, "6", p);
}

function bigGlyph(c: Canvas, glyph: string, p: Palette): void {
  // rough block numeral centred, drawn from a 5x7 bitmap
  const glyphs: Record<string, number[]> = {
    // "5" and "6" as 5-wide bitmaps (1 = pixel on)
    "5": [0b11100, 0b10000, 0b11100, 0b00100, 0b11100],
    "6": [0b01100, 0b10000, 0b11100, 0b10010, 0b01100],
  };
  const rows = glyphs[glyph];
  if (!rows) return;
  const px = 4;
  const ox = Math.floor(c.w / 2 - (5 * px) / 2);
  const oy = Math.floor(c.h * 0.18);
  for (let r = 0; r < rows.length; r++)
    for (let col = 0; col < 5; col++) if (rows[r] & (1 << (4 - col))) c.rect(ox + col * px, oy + r * px, px, px, p.accent);
}

function drawWorldMap(c: Canvas, p: Palette): void {
  c.rect(0, 0, c.w, c.h, p.skyTop);
  // landmasses
  c.disc(28, 30, 14, p.ground);
  c.disc(70, 50, 18, p.ground);
  c.disc(96, 24, 12, p.ground);
  c.disc(40, 64, 10, p.ground);
  c.disc(108, 60, 14, p.ground);
  // realm markers (gold)
  const markers: Array<[number, number]> = [
    [22, 24], [40, 40], [60, 64], [86, 30], [100, 54], [110, 18],
  ];
  for (const [x, y] of markers) {
    c.disc(x, y, 2, p.accent);
    ringRing(c, x, y, 3, p.highlight);
  }
  // compass rose top-right
  c.disc(c.w - 12, 12, 4, p.mid);
  c.line(c.w - 16, 12, c.w - 8, 12, p.highlight);
  c.line(c.w - 12, 8, c.w - 12, 16, p.highlight);
}

// small helper exposed on Canvas-like via function (avoids widening the class)
function ringRing(c: Canvas, cx: number, cy: number, r: number, col: RGB): void {
  for (let y = -r - 1; y <= r + 1; y++)
    for (let x = -r - 1; x <= r + 1; x++) {
      const d = Math.round(Math.sqrt(x * x + y * y));
      if (d === r) c.px(cx + x, cy + y, col);
    }
}

function drawLibrary(c: Canvas, p: Palette): void {
  c.gradient(p.skyTop, p.skyBottom);
  c.rect(0, Math.floor(c.h * 0.7), c.w, c.h, p.ground);
  // back wall shelves
  for (let s = 0; s < 3; s++) {
    const sy = 10 + s * 20;
    c.rect(0, sy + 14, c.w, 2, p.dark);
    for (let bx = 2; bx < c.w - 6; bx += 6) {
      const book = BOOK_COLORS[(bx + s) % BOOK_COLORS.length];
      c.rect(bx, sy, 4, 14, book);
      c.rect(bx, sy, 4, 1, p.highlight);
    }
  }
  // glowing tome on a pedestal
  c.rect(c.w / 2 - 6, Math.floor(c.h * 0.62), 12, 4, p.mid);
  c.rect(c.w / 2 - 4, Math.floor(c.h * 0.55), 8, 8, p.accent);
  c.disc(c.w / 2, Math.floor(c.h * 0.56), 5, p.highlight);
  c.px(c.w / 2, Math.floor(c.h * 0.56), p.skyTop);
}

// ── characters ───────────────────────────────────────────────────────────────
function hero(c: Canvas, portrait: boolean): void {
  const p = HERO;
  const cx = c.w / 2;
  const baseY = portrait ? c.h - 6 : c.h - 8;
  if (portrait) {
    c.disc(cx, c.h / 2, c.h / 2, [16, 20, 38]); // vignette backdrop
    c.disc(cx, c.h / 2, c.h / 2 - 4, [26, 32, 58]);
  }
  // legs
  c.rect(cx - 5, baseY - 8, 4, 8, p.dark);
  c.rect(cx + 1, baseY - 8, 4, 8, p.dark);
  // body (blue tunic)
  c.rect(cx - 7, baseY - 22, 14, 16, p.mid);
  c.rect(cx - 7, baseY - 22, 14, 2, p.accent); // belt
  // chest plate
  c.rect(cx - 4, baseY - 20, 8, 8, p.highlight);
  // head + helmet
  c.disc(cx, baseY - 28, 5, SKIN);
  c.rect(cx - 6, baseY - 32, 12, 3, p.highlight); // helmet
  c.rect(cx - 6, baseY - 30, 2, 4, p.highlight);
  c.rect(cx + 4, baseY - 30, 2, 4, p.highlight);
  // sword
  c.rect(cx + 10, baseY - 26, 2, 18, p.highlight);
  c.rect(cx + 8, baseY - 10, 6, 2, p.accent);
}

function mentor(c: Canvas, portrait: boolean): void {
  const p = MENTOR;
  const cx = c.w / 2;
  const baseY = portrait ? c.h - 6 : c.h - 8;
  if (portrait) {
    c.disc(cx, c.h / 2, c.h / 2, [16, 20, 38]);
    c.disc(cx, c.h / 2, c.h / 2 - 4, [26, 32, 58]);
  }
  // robe
  c.triangle(cx, baseY, 12, baseY - 24, p.mid);
  // staff
  c.rect(cx - 14, baseY - 30, 2, 30, [120, 80, 40]);
  c.disc(cx - 13, baseY - 30, 3, p.accent);
  // head
  c.disc(cx, baseY - 30, 5, SKIN);
  // beard
  c.triangle(cx, baseY - 26, 5, baseY - 18, p.highlight);
  // pointy hat
  c.triangle(cx, baseY - 32, 6, baseY - 44, p.dark);
  c.disc(cx, baseY - 44, 2, p.accent);
}

function creature(c: Canvas, p: Palette, boss: boolean): void {
  const cx = c.w / 2;
  const baseY = c.h - 6;
  const scale = boss ? 1.5 : 1;
  const bodyW = Math.round(16 * scale);
  const bodyH = Math.round(14 * scale);
  const topY = baseY - Math.round(30 * scale);
  // body
  c.ellipse(cx, topY + Math.round(bodyH / 2), bodyW, bodyH, p.accent);
  // belly shade
  c.ellipse(cx, topY + bodyH, Math.round(bodyW * 0.6), Math.round(bodyH * 0.4), lerpC(p.accent, p.highlight, 0.4));
  // horns / spikes
  c.triangle(cx - bodyW, topY + 2, 3, topY - 4, p.dark);
  c.triangle(cx + bodyW, topY + 2, 3, topY - 4, p.dark);
  if (boss) c.triangle(cx, topY - 4, 2, topY - 10, p.dark);
  // eyes
  c.disc(cx - 4, topY + 4, 2, p.dark);
  c.disc(cx + 4, topY + 4, 2, p.dark);
  c.px(cx - 4, topY + 4, p.highlight);
  c.px(cx + 4, topY + 4, p.highlight);
  // mouth
  c.rect(cx - 3, topY + 9, 7, 1, p.dark);
}

// ── plates (themed illustration with a math motif) ────────────────────────────
function plate(c: Canvas, realmId: RealmId): void {
  const themeId = REALM_THEME_ID[realmId];
  const p = THEME[themeId];
  c.gradient(p.skyTop, p.skyBottom);
  const groundY = Math.floor(c.h * 0.72);
  c.rect(0, groundY, c.w, c.h - groundY, p.ground);
  // a sun/moon
  c.disc(c.w - 18, 16, 6, p.highlight);
  // theme silhouette on the left
  switch (themeId) {
    case "forest": tree(c, 20, groundY + 10, 26, p); tree(c, 40, groundY + 12, 18, p); break;
    case "dunes": dune(c, 26, groundY + 10, 22, p); dune(c, 56, groundY + 14, 26, p); break;
    case "volcano": volcano(c, 28, groundY + 12, 16, p); break;
    case "reef": coral(c, 22, groundY + 12, 16, p); coral(c, 44, groundY + 14, 20, p); break;
    case "quarry": stoneBlock(c, 16, groundY - 4, 18, 12, p); stoneBlock(c, 40, groundY, 14, 8, p); break;
    case "atoll": island(c, 26, groundY + 4, 16, p); break;
    default: break;
  }
  // math motif panel on the right (a parchment card with a themed glyph)
  const px = c.w - 56;
  const py = 18;
  const pw = 44;
  const ph = 40;
  c.rect(px - 2, py - 2, pw + 4, ph + 4, p.dark);
  c.rect(px, py, pw, ph, [233, 217, 174]); // parchment
  c.rect(px, py, pw, 2, [201, 178, 124]);
  // motif per realm
  drawMotif(c, realmId, px, py, pw, ph, p);
}

function drawMotif(c: Canvas, realmId: RealmId, x: number, y: number, w: number, h: number, p: Palette): void {
  const ink: RGB = [58, 42, 20];
  const cx = x + w / 2;
  const cy = y + h / 2;
  switch (realmId) {
    case "g5-fractions": {
      // a pie split into 4, one quarter shaded
      for (let i = 0; i < 4; i++) {
        c.rect(x + 8 + i * 7, y + 8, 6, h - 18, i === 0 ? ink : [201, 178, 124]);
      }
      break;
    }
    case "g5-decimals": {
      // a place-value grid: 1 . 2 3
      for (let i = 0; i < 4; i++) c.rect(x + 6 + i * 8, cy - 6, 6, 12, i === 1 ? [242, 185, 47] : [201, 178, 124]);
      break;
    }
    case "g5-volume": {
      // a cube (3 faces)
      c.rect(cx - 8, cy - 6, 16, 12, lerpC(ink, p.accent, 0.2));
      c.rect(cx - 12, cy - 10, 8, 8, lerpC(ink, p.accent, 0.4));
      break;
    }
    case "g6-ratios": {
      // two columns ratio 2:3
      c.rect(cx - 9, cy - 8, 4, 16, ink);
      c.rect(cx - 3, cy - 8, 6, 16, lerpC(ink, p.accent, 0.3));
      break;
    }
    case "g6-fracdiv": {
      // a ÷ b: a bar with dots
      c.disc(cx - 8, cy - 6, 2, ink);
      c.rect(cx - 5, cy - 1, 18, 2, ink);
      c.disc(cx + 10, cy + 6, 2, ink);
      break;
    }
    case "g6-area": {
      // a triangle (area)
      c.triangle(cx, cy + 8, 10, cy - 8, ink);
      break;
    }
    default:
      break;
  }
}

// ── slot registry ────────────────────────────────────────────────────────────
type Category = "scene" | "character" | "plate";
interface Slot {
  name: string;
  category: Category;
  themeId: string; // for scenes/plates
  transparent: boolean; // characters float; portraits are framed (opaque)
  portrait: boolean;
}

function buildSlots(): Slot[] {
  const slots: Slot[] = [];
  const addScene = (name: string, themeId: string) => slots.push({ name, category: "scene", themeId, transparent: false, portrait: false });
  addScene("landing", "landing");
  addScene("grade-5", "forest");
  addScene("grade-6", "atoll");
  addScene("world-map", "map");
  addScene("library", "library");
  for (const id of ENABLED_REALMS) addScene(`realm-${id}`, REALM_THEME_ID[id]);

  slots.push({ name: "hero-full", category: "character", themeId: "forest", transparent: true, portrait: false });
  slots.push({ name: "hero-portrait", category: "character", themeId: "forest", transparent: false, portrait: true });
  slots.push({ name: "mentor-full", category: "character", themeId: "forest", transparent: true, portrait: false });
  slots.push({ name: "mentor-portrait", category: "character", themeId: "forest", transparent: false, portrait: true });
  for (const id of ENABLED_REALMS) slots.push({ name: `minion-${id}`, category: "character", themeId: REALM_THEME_ID[id], transparent: true, portrait: false });
  for (const id of ENABLED_REALMS) slots.push({ name: `boss-${id}`, category: "character", themeId: REALM_THEME_ID[id], transparent: true, portrait: false });

  for (const id of ENABLED_REALMS) slots.push({ name: `plate-${id}`, category: "plate", themeId: REALM_THEME_ID[id], transparent: false, portrait: false });
  return slots;
}

async function processRaw(slot: Slot, artSrc: string): Promise<Buffer | null> {
  const raw = path.join(artSrc, `${slot.name}.png`);
  if (!fs.existsSync(raw)) return null;
  // downscale to logical, quantise, then nearest-neighbour upscale for pixel look
  const small = await sharp(raw).resize(LW, LH, { fit: "cover" }).png({ palette: true, colors: 48 }).toBuffer();
  return sharp(small).resize(OUT_W, OUT_H, { kernel: "nearest" }).png().toBuffer();
}

async function renderSlot(slot: Slot, artSrc: string): Promise<Buffer> {
  const raw = await processRaw(slot, artSrc);
  if (raw) return raw;
  const c = new Canvas(LW, LH);
  if (slot.category === "scene") scene(c, slot.name, slot.themeId);
  else if (slot.category === "plate") plate(c, slot.name.replace(/^plate-/, "") as RealmId);
  else if (slot.name.startsWith("hero")) hero(c, slot.portrait);
  else if (slot.name.startsWith("mentor")) mentor(c, slot.portrait);
  else creature(c, THEME[slot.themeId], slot.name.startsWith("boss"));
  return toPng(c, !slot.transparent);
}

async function main(): Promise<void> {
  const root = process.cwd();
  const artDir = path.join(root, "public", "art");
  const artSrc = path.join(root, "art-src");
  fs.mkdirSync(artDir, { recursive: true });

  const slots = buildSlots();
  let total = 0;
  let generated = 0;
  let processed = 0;
  for (const slot of slots) {
    const buf = await renderSlot(slot, artSrc);
    fs.writeFileSync(path.join(artDir, `${slot.name}.png`), buf);
    total += buf.length;
    if (fs.existsSync(path.join(artSrc, `${slot.name}.png`))) processed += 1;
    else generated += 1;
    console.log(`${slot.name}.png  ${(buf.length / 1024).toFixed(1)} KB`);
  }
  console.log(`\n${slots.length} slots written to public/art/ (${generated} generated, ${processed} processed from art-src/) — ${(total / 1024).toFixed(1)} KB total`);
}

void main().catch((error) => {
  console.error(error);
  process.exit(1);
});
